package com.bank.payments.adapters.out.jdbc;

import com.bank.payments.domain.model.Order;
import com.bank.payments.domain.port.OrderRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.util.List;
import java.util.Optional;

/** JDBC adapter of the OrderRepository port (legacy file ORDENES). */
@Repository
public class JdbcOrderRepository implements OrderRepository {

    private final JdbcTemplate jdbcTemplate;

    public JdbcOrderRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public Optional<Order> findByKeyForUpdate(Integer orderNumber, Integer companyNumber) {
        List<Order> orders = jdbcTemplate.query(
                "SELECT order_number, company_number, status, order_value, movement_number, commission "
                        + "FROM payment_orders WHERE order_number = ? AND company_number = ? FOR UPDATE",
                (rs, rowNum) -> {
                    int number = rs.getInt("order_number");
                    int company = rs.getInt("company_number");
                    String status = rs.getString("status");
                    BigDecimal value = rs.getBigDecimal("order_value");
                    long movement = rs.getLong("movement_number");
                    Long movementNumber = rs.wasNull() ? null : movement;
                    BigDecimal commission = rs.getBigDecimal("commission");
                    return new Order(number, company, status, value, movementNumber, commission);
                },
                orderNumber, companyNumber);
        return orders.stream().findFirst();
    }

    @Override
    public void markPaid(Integer orderNumber, Integer companyNumber, Long movementNumber, BigDecimal commission) {
        jdbcTemplate.update(
                "UPDATE payment_orders SET status = 'G', movement_number = ?, commission = ? "
                        + "WHERE order_number = ? AND company_number = ?",
                movementNumber, commission, orderNumber, companyNumber);
    }
}
